import {elementPoint} from './canvas-coordinates.js?v=20261025-release1';
import {paintStrokes} from './drawing.js?v=20261025-release1';
import {layerVisible} from './layers.js?v=20261025-release1';
// Proposals live over the actual paper until Apply; no cut or stroke is changed.
export function setupPanelRecognition({getProject,apply,toast}){
 const paper=document.getElementById('paper'),viewport=document.getElementById('viewport');
 const button=document.createElement('button');button.id='recognizePanels';button.textContent='▣ 컷 인식';button.title='원고 위에서 컷선 인식 · 편집';const actions=document.createElement('div');actions.className='cut-creation-actions';const add=document.getElementById('addCut');add.before(actions);add.hidden=true;actions.append(button);
 const bar=document.createElement('section');bar.id='recognitionToolbar';bar.hidden=true;bar.setAttribute('aria-label','캔버스 컷 인식');
 bar.innerHTML='<strong>컷 자동으로 인식하기</strong><label class="check"><input id="recognitionBalloons" type="checkbox"> 말풍선도 인식</label><button id="recognitionRun">다시 인식</button><button id="recognitionAdd">＋ 직접 그리기</button><select id="recognitionShape" aria-label="인식 형태"><option value="rectangle">직사각형 우선</option><option value="free">기울기 유지</option></select><label>선 <input id="recognitionWidth" type="number" min="1" max="30" value="8" aria-label="인식 컷 선 두께">px</label><details><summary>설정</summary><label>틈 연결 <input id="recognitionGap" type="number" min="1" max="10" value="3"></label><label class="check"><input id="recognitionFade" type="checkbox" checked> 적용 후 러프 30%</label><button id="recognitionImport">이미지에서 인식</button><input id="recognitionFile" type="file" accept="image/png,image/jpeg,image/webp" hidden></details><span id="recognitionStatus" role="status"></span><button id="recognitionPrevious" title="이전 후보">↑</button><button id="recognitionNext" title="다음 후보">↓</button><select id="recognitionKind" aria-label="선택 후보 종류"><option value="panel">컷</option><option value="balloon">말풍선</option></select><button id="recognitionExclude">선택 제외</button><button id="recognitionApply" class="primary">적용 ↵</button><button id="recognitionCancel">취소 Esc</button>';
 viewport.parentElement.append(bar);const $=id=>bar.querySelector('#'+id);
 const ns='http://www.w3.org/2000/svg',overlay=document.createElementNS(ns,'svg');overlay.id='recognitionOverlay';overlay.setAttribute('preserveAspectRatio','none');overlay.setAttribute('aria-label','컷 후보 · 드래그로 이동, 꼭짓점으로 크기 조절');
 let project=null,pageId=null,candidates=[],selected=-1,worker=null,epoch=0,drag=null,imported=null,source=null,adding=false;
 const active=()=>!bar.hidden;
 function close(){epoch++;worker?.terminate();worker=null;bar.hidden=true;overlay.remove();source?.remove();document.body.classList.remove('recognizing-panels');drag=null;imported?.close();imported=null;}
 function attach(){if(!active())return;if(project!==getProject()||project.activePage!==pageId)return close();if(overlay.parentElement!==paper)paper.append(overlay);}
 new MutationObserver(attach).observe(paper,{childList:true});
 function status(){$('recognitionKind').disabled=selected<0;$('recognitionKind').value=candidates[selected]?.kind||'panel';const count=candidates.filter(c=>c.enabled).length;$('recognitionStatus').textContent=`${count}개 선택${selected>=0?' · 후보 '+(selected+1):''} · 드래그로 편집`;$('recognitionExclude').disabled=selected<0;$('recognitionExclude').textContent=candidates[selected]?.enabled===false?'선택 복원':'선택 제외';}
 function svg(tag,attrs,parent=overlay){const el=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))el.setAttribute(k,String(v));parent.append(el);return el;}
 function draw(){if(!active())return;attach();overlay.setAttribute('viewBox',`0 0 ${project.width} ${project.pageHeight}`);overlay.replaceChildren();const z=paper.getBoundingClientRect().width/project.width,handle=9/z;
  candidates.forEach((b,i)=>{const group=svg('g',{'data-candidate':i,class:(b.enabled?'':'excluded ')+(i===selected?'selected':'')});const points=(b.path||[[0,0],[1,0],[1,1],[0,1]]).map(([x,y])=>`${b.x+x*b.w},${b.y+y*b.h}`).join(' ');svg(b.kind==='balloon'?'ellipse':'polygon',{...(b.kind==='balloon'?{cx:b.x+b.w/2,cy:b.y+b.h/2,rx:b.w/2,ry:b.h/2}:{points}),'stroke-width':+$('recognitionWidth').value||8,'data-drag':'move'},group);const text=svg('text',{x:b.x+6/z,y:b.y+22/z,'font-size':14/z},group);text.textContent=(b.kind==='balloon'?'말풍선 ':'컷 ')+(i+1)+(b.enabled?'':' · 제외');
   if(i===selected)for(const [key,x,y]of [['nw',0,0],['n',.5,0],['ne',1,0],['e',1,.5],['se',1,1],['s',.5,1],['sw',0,1],['w',0,.5]])svg('rect',{x:b.x+b.w*x-handle/2,y:b.y+b.h*y-handle/2,width:handle,height:handle,'data-drag':key,class:'recognition-handle'},group);
  });status();
 }
 new ResizeObserver(()=>{if(active())draw();}).observe(paper);
 async function run(){const id=++epoch;worker?.terminate();worker=null;attach();if(!active())return;const base=project.cuts.find(c=>c.pageId===pageId&&c.pageBase);if(!base)return toast('페이지 러프를 찾을 수 없습니다.');const w=Math.round(Math.min(560,project.width*6000/project.pageHeight)),h=Math.round(project.pageHeight/project.width*w),canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const cx=canvas.getContext('2d',{willReadFrequently:true});const seeds=[],roughStrokes=[];
  if(imported){cx.drawImage(imported,0,0,w,h);source?.remove();source=canvas;source.className='recognition-source';paper.append(source);}else{source?.remove();source=null;for(const l of base.paintLayers)if(layerVisible(base,l)){const strokes=base.strokes.filter(s=>(s.layerId||'rough')===l.id);paintStrokes(cx,strokes,w,h);roughStrokes.push(...strokes);for(const s of strokes){if(s.erase||s.kind==='fill'||s.fillRuns||s.points.length<4)continue;let x=1,y=1,right=0,bottom=0;for(const point of s.points){x=Math.min(x,point[0]);y=Math.min(y,point[1]);right=Math.max(right,point[0]);bottom=Math.max(bottom,point[1]);}seeds.push({x:x*w,y:y*h,w:(right-x)*w,h:(bottom-y)*h});}}}
  $('recognitionStatus').textContent='컷선을 분석하는 중…';$('recognitionApply').disabled=true;const bytes=cx.getImageData(0,0,w,h);worker=new Worker(new URL('./panel-worker.js?v=20261025-release1',import.meta.url),{type:'module'});
  worker.onmessage=({data:d})=>{if(id!==epoch)return;worker.terminate();worker=null;$('recognitionApply').disabled=false;if(d.error){$('recognitionStatus').textContent=d.error;return;}candidates=d.candidates.map(b=>({...b,x:b.x/w*project.width,y:b.y/w*project.width,w:b.w/w*project.width,h:b.h/w*project.width,tailPoint:b.tailPoint?.map(v=>v/w*project.width),enabled:true}));selected=candidates.length?0:-1;draw();};
  worker.onerror=()=>{if(id===epoch){$('recognitionStatus').textContent='인식 실패 · 직접 그리기 또는 다시 인식';$('recognitionApply').disabled=false;}worker?.terminate();};worker.postMessage({bytes:bytes.data.buffer,w,h,options:{shape:$('recognitionShape').value,gap:+$('recognitionGap').value,balloons:$('recognitionBalloons').checked,minWidth:80/project.width*w,minHeight:160/project.width*w,seeds,strokes:imported?null:roughStrokes}},[bytes.data.buffer]);
 }
 button.onclick=()=>{if(active())return close();project=getProject();if(!project.pages)return toast('페이지 모드의 러프에서 사용할 수 있습니다.');pageId=project.activePage;candidates=[];selected=-1;bar.hidden=false;document.body.classList.add('recognizing-panels');attach();run();};
 $('recognitionRun').onclick=()=>{imported?.close();imported=null;run();};$('recognitionShape').onchange=run;$('recognitionBalloons').onchange=run;$('recognitionWidth').oninput=draw;$('recognitionCancel').onclick=close;
 $('recognitionAdd').onclick=()=>{adding=!adding;$('recognitionAdd').classList.toggle('active',adding);overlay.classList.toggle('adding',adding);};
 $('recognitionKind').onchange=()=>{if(selected>=0){candidates[selected].kind=$('recognitionKind').value;draw();}};
 $('recognitionExclude').onclick=()=>{if(selected<0)return;candidates[selected].enabled=!candidates[selected].enabled;draw();};
 function next(delta){if(!candidates.length)return;selected=(selected+delta+candidates.length)%candidates.length;draw();const b=candidates[selected],r=paper.getBoundingClientRect(),v=viewport.getBoundingClientRect(),z=r.width/project.width;viewport.scrollBy({top:r.top+b.y*z-v.top-90,left:r.left+b.x*z-v.left-30,behavior:'instant'});}
 $('recognitionPrevious').onclick=()=>next(-1);$('recognitionNext').onclick=()=>next(1);
 const point=e=>{const p=elementPoint(paper,e);return {x:Math.max(0,Math.min(project.width,p[0]*project.width)),y:Math.max(0,Math.min(project.pageHeight,p[1]*project.pageHeight))};};
 overlay.onpointerdown=e=>{if(e.button!==0||viewport.matches('.space-pan,.canvas-panning'))return;e.preventDefault();e.stopPropagation();const p=point(e),g=e.target.closest('[data-candidate]');if(adding||!g){candidates.push({x:p.x,y:p.y,w:1,h:1,enabled:true});selected=candidates.length-1;drag={...p,kind:'new',original:{...candidates[selected]}};}else{selected=+g.dataset.candidate;drag={...p,kind:e.target.dataset.drag||'move',original:{...candidates[selected]}};}overlay.setPointerCapture(e.pointerId);draw();};
 overlay.onpointermove=e=>{if(!drag)return;const p=point(e),b=candidates[selected],o=drag.original,dx=p.x-drag.x,dy=p.y-drag.y;if(drag.kind==='new'){Object.assign(b,{x:Math.min(p.x,drag.x),y:Math.min(p.y,drag.y),w:Math.abs(dx),h:Math.abs(dy)});}else if(drag.kind==='move'){b.x=Math.max(0,Math.min(project.width-o.w,o.x+dx));b.y=Math.max(0,Math.min(project.pageHeight-o.h,o.y+dy));}else{let l=o.x,t=o.y,r=o.x+o.w,bt=o.y+o.h;const k=drag.kind,minW=b.kind==='balloon'?30:80,minH=b.kind==='balloon'?30:160;if(k.includes('w'))l=Math.max(0,Math.min(r-minW,l+dx));if(k.includes('e'))r=Math.min(project.width,Math.max(l+minW,r+dx));if(k.includes('n'))t=Math.max(0,Math.min(bt-minH,t+dy));if(k.includes('s'))bt=Math.min(project.pageHeight,Math.max(t+minH,bt+dy));Object.assign(b,{x:l,y:t,w:r-l,h:bt-t});}draw();};
 overlay.onpointerup=()=>{if(!drag)return;const b=candidates[selected];if(drag.kind==='new'&&(b.w<80||b.h<160)){candidates.splice(selected,1);selected=candidates.length-1;}drag=null;adding=false;$('recognitionAdd').classList.remove('active');overlay.classList.remove('adding');draw();};overlay.onpointercancel=()=>{if(drag){if(drag.kind==='new')candidates.splice(selected,1);else candidates[selected]=drag.original;drag=null;selected=Math.min(selected,candidates.length-1);draw();}};
 $('recognitionApply').onclick=()=>{if(project!==getProject()||project.activePage!==pageId)return close();const rects=candidates.filter(c=>c.enabled).map(({x,y,w,h,path,kind,tailPoint})=>({x:Math.round(x),y:Math.round(y),w:Math.round(w),h:Math.round(h),path,kind,tailPoint}));if(!rects.length)return toast('적용할 컷 후보를 선택하세요.');if(rects.some(r=>r.w<60||r.h<(r.kind==='balloon'?40:160)||r.h>5000||r.x+r.w>project.width+1||r.y+r.h>project.pageHeight+1))return toast('컷 크기를 확인하세요. 높이 160–5000px가 필요합니다.');const fade=$('recognitionFade').checked,width=Math.max(1,Math.min(30,+$('recognitionWidth').value||8));close();apply(rects,fade,width);};
 document.addEventListener('keydown',e=>{if(!active()||e.isComposing)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();close();}else if(!e.target.matches('input,select,textarea')&&['Enter','Delete','Backspace'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();(e.key==='Enter'?$('recognitionApply'):$('recognitionExclude')).click();}},true);
 $('recognitionImport').onclick=()=>$('recognitionFile').click();$('recognitionFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>30000000)throw Error('이미지는 30MB 이하로 선택하세요.');const bitmap=await createImageBitmap(file);if(bitmap.width*bitmap.height>64000000){bitmap.close();throw Error('이미지는 6,400만 픽셀 이하로 선택하세요.');}if(!active()){bitmap.close();return;}imported?.close();imported=bitmap;run();}catch(e){toast(e.message);}};
}
